INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C017', '眠れない夜の呼吸観察', '{}', 'practice', '教材内の実践', '実践', '呼吸を操作せず観察する', ARRAY['呼吸を変えようとせず、吸う息・吐く息に気づく。','考え事に気づいたら「考えている」と気づき、呼吸へ戻る。']::text[], ARRAY['P096','P205']::text[], ARRAY['K038','K039']::text[], ARRAY['S002','S004']::text[], false, false, '[{"variant_id":"C017-V01","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"眠くなるまでという一覧表記。無期限に続ける実践指示としては採用しない。","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]'::jsonb, '[]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C018', '姿勢リセット呼吸', ARRAY['肩こりリセット呼吸']::text[], 'practice', '教材内の実践', '実践', '姿勢と力みの観察', ARRAY['背すじを軽く伸ばし、一度肩をすくめてストンと落とす。','鼻から3〜4秒吸い、肋骨が横と後ろに広がるのを感じる。','口または鼻から6秒吐き、首・肩・あごの力を抜く。']::text[], ARRAY['P097','P120','P214']::text[], ARRAY['K041','K042','K043','K048','K049','K084']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C019', '朝の目覚め呼吸', ARRAY['目覚めの呼吸']::text[], 'practice', '教材内の実践', '実践', '起床後の準備', ARRAY['座るか立って背すじを軽く伸ばす。','肩・あご・お腹の力を抜き、鼻から3秒吸う。','胸・背中・肋骨の広がりを感じ、口または鼻から4〜5秒吐く。']::text[], ARRAY['P098','P120']::text[], ARRAY['K041','K042','K043','K048','K049']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C020', '手足あたため呼吸', '{}', 'practice', '教材内の実践', '実践', '冷えたときの体の観察', ARRAY['楽に座るか仰向けになる。両手をお腹に当てる。','鼻から4秒静かに吸い、お腹・背中・肋骨のやさしい広がりを感じる。','口または鼻から6秒吐き、肩・手・足の力を抜く。']::text[], ARRAY['P099','P120']::text[], ARRAY['K041','K042','K043','K048','K049']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;